// This Dart code defines a map containing colleges and their minimum required scores
// for the AP Environmental Science examination. Only colleges with a specified policy
// for this subject are included.

Map<String, int>? getApCreditPolicy(String exam) {
  switch (exam) {
    case 'AP 2-D Art and Design':
      return ap2DArtCreditPolicy;
    case 'AP 3-D Art and Design':
      return ap3DArtCreditPolicy;
    case 'AP Calculus BC':
      return apCalculusBCCreditPolicy;
    case 'AP African American Studies':
      return apAfricanAmericanStudiesCreditPolicy;
    case 'AP Art History':
      return apArtHistoryCreditPolicy;
    case 'AP Biology':
      return apBiologyCreditPolicy;
    case 'AP Calculus AB with Calculus BC Subscore':
      return apCalculusABCreditPolicy;
    case 'AP Calculus AB':
      return apCalculusABCreditPolicy;
    case 'AP Chemistry':
      return apChemistryCreditPolicy;
    case 'AP Chinese Language and Culture':
      return apChineseLanguageAndCultureCreditPolicy;
    case 'AP Comparative Government and Politics':
      return apComparativeGovernmentAndPoliticsCreditPolicy;
    case 'AP Computer Science A':
      return apComputerScienceACreditPolicy;
    case 'AP Computer Science Principles':
      return apComputerSciencePrinciplesCreditPolicy;
    case 'AP English Language and Composition':
      return apEnglishLanguageAndCompositionCreditPolicy;
    case 'AP English Literature and Composition':
      return apEnglishLiteratureAndCompositionCreditPolicy;
    case 'AP Environmental Science':
      return apEnvironmentalScienceCreditPolicy;
    case 'AP European History':
      return apEuropeanHistoryCreditPolicy;
    case 'AP French Language and Culture':
      return apFrenchLanguageAndCultureCreditPolicy;
    case 'AP German Language and Culture':
      return apGermanLanguageAndCultureCreditPolicy;
    case 'AP Human Geography':
      return apHumanGeographyCreditPolicy;
    case 'AP Italian Language and Culture': 
      return apItalianLanguageAndCultureCreditPolicy;
    case 'AP Japanese Language and Culture':
      return apJapaneseLanguageAndCultureCreditPolicy;
    case 'AP Latin':
      return apLatinCreditPolicy;
    case 'AP Macroeconomics':
      return apMacroeconomicsCreditPolicy;
    case 'AP Music Theory':
      return apMusicTheoryCreditPolicy;
    case 'AP Physics 1':
      return apPhysics1CreditPolicy;
    case 'AP Physics 2':
      return apPhysics2CreditPolicy;
    case 'AP Physics C - Electricity and Magnetism':
      return apPhysicsCElectricityAndMagnetismCreditPolicy;
    case 'AP Physics C - Mechanics':
      return apPhysicsCMechanicsCreditPolicy;
    case 'AP Psychology':
      return apPsychologyCreditPolicy;
    case 'AP Spanish Language and Culture':
      return apSpanishLanguageAndCultureCreditPolicy;
    case 'AP Spanish Literature and Culture':
      return apSpanishLiteratureAndCultureCreditPolicy;
    case 'AP Statistics':
      return apStatisticsCreditPolicy;
    case 'AP United States Government and Politics':
      return apUnitedStatesGovernmentAndPoliticsCreditPolicy;
    case 'AP United States History':  
      return apUnitedStatesHistoryCreditPolicy;
    case 'AP World History: Modern': 
      return apWorldHistoryModernCreditPolicy;
    case 'AP Microeconomics':
      return apMicroeconomicsCreditPolicy;
      

    default:
      return null;
  }
}
